"""Bootstrap scripts uploaded into sandboxes (they never contain credentials)."""

# Under OpenShell, requests to the controller are authenticated by the gateway (it injects the
# bearer); nothing here holds a credential. LEGION_ACCESS_TOKEN only exists with LocalRunner.
GIT_AUTH = r"""
git_auth() {
  if [ -n "${LEGION_ACCESS_TOKEN:-}" ]; then
    git -c http.extraHeader="Authorization: Bearer $LEGION_ACCESS_TOKEN" "$@"
  else
    git "$@"
  fi
}
"""

RUN_AGENT_SH = r"""#!/usr/bin/env bash
# Generated by legion-orch. Prepares the working copy from the controller's git remote and starts
# the agent. Re-entrant: rework runs in the same sandbox reuse /sandbox/work.
set -euo pipefail
SB="$(cd "$(dirname "$0")/.." && pwd)"   # <sandbox root>/payload/<this script>
P="$SB/payload"
set -a; source "$P/run.env"; set +a
""" + GIT_AUTH + r"""
echo "[legion] setup: run ${LEGION_RUN_ID:-?} (${LEGION_ROLE:-?}) in $SB"
if [ "$LEGION_NEEDS_REPO" = "1" ]; then
  if [ ! -d "$SB/work/.git" ]; then
    echo "[legion] cloning $LEGION_GIT_URL"
    git_auth clone --quiet "$LEGION_GIT_URL" "$SB/work"
  fi
  cd "$SB/work"
  git config --unset-all http.extraHeader 2>/dev/null || true
  git config user.name "legion-$LEGION_ROLE"
  git config user.email "$LEGION_RUN_ID@legion.local"
  if [ -n "${LEGION_ACCESS_TOKEN:-}" ]; then
    # local development only: emulate the gateway's injection for the agent's own git calls
    git config http.extraHeader "Authorization: Bearer $LEGION_ACCESS_TOKEN"
  fi
  git fetch --quiet origin
  git cat-file -e "$LEGION_BASE_SHA^{commit}" 2>/dev/null || git fetch --quiet origin "$LEGION_BASE_SHA"
  if git rev-parse --verify --quiet "refs/heads/$LEGION_BRANCH" >/dev/null; then
    git checkout --quiet "$LEGION_BRANCH"
  elif git rev-parse --verify --quiet "refs/remotes/origin/$LEGION_BRANCH" >/dev/null; then
    # a fresh sandbox (e.g. after a retry) continues from what earlier runs pushed
    git checkout --quiet -B "$LEGION_BRANCH" "origin/$LEGION_BRANCH"
  else
    git checkout --quiet -B "$LEGION_BRANCH" "$LEGION_BASE_SHA"
  fi
  # the repository's setup (mise.toml's `setup` task, pinned): the agent starts with it done;
  # a failure is logged, and the agent may still work
  if [ -n "${LEGION_SETUP_PIN:-}" ]; then
    echo "[legion] setup: mise run setup"
    if timeout "${LEGION_SETUP_TIMEOUT:-900}" bash "$P/mise-setup.sh"; then
      echo "[legion] setup done"
    else
      echo "[legion] setup failed (exit $?): the working copy may lack its dependencies" >&2
    fi
  fi
else
  mkdir -p "$SB/work"; cd "$SB/work"
fi
# The agent command finds its inputs through these, under any runner (/sandbox in OpenShell).
export LEGION_PAYLOAD="$P" LEGION_MCP_CONFIG="$P/mcp.json"
# The run's skills, loaded on demand by the agent: replace any legion-* skills an earlier run in
# this sandbox installed (a payload without skills keeps them).
if [ -d "$P/skills" ]; then
  SKILLS="${CLAUDE_CONFIG_DIR:-$HOME/.claude}/skills"
  mkdir -p "$SKILLS"
  rm -rf "$SKILLS"/legion-*
  cp -R "$P/skills/." "$SKILLS/"
  echo "[legion] installed $(ls "$P/skills" | wc -l | tr -d ' ') skills into $SKILLS"
fi
# A rework continues the earlier session (Claude Code keeps it under its config dir) if the
# sandbox still has it; otherwise the agent starts a new one.
if [ -n "${LEGION_RESUME_SESSION:-}" ]; then
  if find "${CLAUDE_CONFIG_DIR:-$HOME/.claude}/projects" -name "$LEGION_RESUME_SESSION.jsonl" \
       2>/dev/null | grep -q .; then
    echo "[legion] resuming agent session $LEGION_RESUME_SESSION"
  else
    if [ "${LEGION_REQUIRE_SESSION:-0}" = "1" ]; then
      echo "[legion] agent session $LEGION_RESUME_SESSION not found" >&2
      exit 3
    fi
    echo "[legion] agent session $LEGION_RESUME_SESSION not found; starting a new one"
    unset LEGION_RESUME_SESSION
  fi
fi
echo "[legion] starting the agent in $PWD"
exec bash -lc "$LEGION_AGENT_COMMAND"
"""

VERIFY_SETUP_SH = r"""#!/usr/bin/env bash
# Generated by legion-orch. Deterministic verifier: read-only clone of the commit under test.
set -euo pipefail
SB="$(cd "$(dirname "$0")/.." && pwd)"   # <sandbox root>/payload/<this script>
source "$SB/payload/run.env"
""" + GIT_AUTH + r"""
git_auth clone --quiet --no-checkout "$LEGION_GIT_URL" "$SB/work"
cd "$SB/work"
git cat-file -e "$1^{commit}" 2>/dev/null || git_auth fetch --quiet origin "$1"
git checkout --quiet --detach "$1"
"""

MISE_SETUP_SH = r"""#!/usr/bin/env bash
# Generated by legion-orch. The repository's setup: mise.toml's `setup` task, only from the
# version the controller pinned (G-MS1) – an agent's edit to it is never run. Run in the checkout.
set -euo pipefail
pin="${1:-${LEGION_SETUP_PIN:-}}"
got="$(git rev-parse HEAD:mise.toml 2>/dev/null || true)"
if [ "$got" != "$pin" ]; then
  echo "G-MS1: mise.toml at HEAD (${got:-missing}) is not the pinned version ($pin): setup not run" >&2
  exit 3
fi
export MISE_YES=1
mise trust --quiet mise.toml
exec mise run setup
"""
